13	const keyExtractor = (item: EventTimelineItem) => {
14	  const eventId = item.eventOrTransactionId;
15	  if (eventId?.tag === "EventId") return eventId.inner.eventId;
16	  if (eventId?.tag === "TransactionId") return eventId.inner.transactionId;
