24	const NUM_COLUMNS = 4;
25	const SPACING = 2;
26	const HORIZONTAL_SPACING = 40; // Each padding is 20px
27	const { width: SCREEN_WIDTH } = Dimensions.get("window");
28	const ITEM_SIZE =
29	  (SCREEN_WIDTH - SPACING * (NUM_COLUMNS + 1) - HORIZONTAL_SPACING) /
