32	interface MediaThumbnailProps {
33	  item: EventTimelineItem;
34	  onPress: (uri: string | null, type?: "image" | "video") => void;
35	}
36	
37	function getMediaInfo(item: EventTimelineItem): {
38	  type: "image" | "video";
39	  content: ImageMessageContent | VideoMessageContent;
40	} | null {
41	  if (item.content.tag === TimelineItemContent_Tags.MsgLike) {
42	    const content = item.content.inner.content;
43	    if (content.kind.tag === MsgLikeKind_Tags.Message) {
44	      const msgType = content.kind.inner.content.msgType;
45	      if (msgType?.tag === MessageType_Tags.Image) {
46	        return { type: "image", content: msgType.inner.content };
47	      }
48	      if (msgType?.tag === MessageType_Tags.Video) {
49	        return { type: "video", content: msgType.inner.content };
50	      }
51	    }
52	  }
53	  return null;
54	}
55	
56	export const MediaThumbnail: FC<MediaThumbnailProps> = ({ item, onPress }) => {
57	  const [uri, setUri] = useState<string | null>(null);
58	  const [info, setInfo] = useState<{
59	    type: "image" | "video";
60	    content: ImageMessageContent | VideoMessageContent;
61	  } | null>(null);
62	  const [loading, setLoading] = useState(true);
63	
64	  useEffect(() => {
65	    const loadMedia = async () => {
66	      try {
67	        setLoading(true);
68	        const info = getMediaInfo(item);
69	        setInfo(info);
70	
71	        if (!info) return;
72	
73	        const mxcUrl = info?.content.source.url();
74	        if (!mxcUrl) return;
75	
76	        if (await isCached(mxcUrl)) {
77	          setUri(getCachedImagePathByURL(mxcUrl));
78	          return;
79	        }
80	
81	        const url = await fetchMedia({
82	          serverUrl:
83	            MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
84	          mediaSource: info.content.source,
85	          mimeType:
86	            info.type === "image"
87	              ? info.content.info?.mimetype || "image/jpeg"
88	              : info.content.info?.mimetype || "video/mp4",
89	        });
90	
91	        if (!url) return;
92	
93	        await cacheImageWithKey(mxcUrl, url);
94	        setUri(getCachedImagePathByURL(mxcUrl));
95	      } catch (e) {
96	        console.error("Failed to load media thumbnail:", e);
97	      } finally {
98	        setLoading(false);
99	      }
100	    };
101	
102	    loadMedia();
103	  }, [item]);
104	
105	  return (
106	    <Button.Wrapper onPress={() => onPress(uri, info?.type)}>
107	      {uri ? (
108	        <Block
109	          width={ITEM_SIZE}
110	          height={ITEM_SIZE}
111	          background={Colors.white20}
112	          border={{
113	            borderRadius: 4,
114	          }}
115	          overflow="hidden"
116	        >
117	          {info?.type === "image" ? (
118	            <Image
119	              source={{ uri }}
120	              width={ITEM_SIZE}
121	              height={ITEM_SIZE}
122	              resizeMode="cover"
123	            />
124	          ) : (
125	            <Video
126	              source={{ uri }}
127	              style={{
128	                width: ITEM_SIZE,
129	                height: ITEM_SIZE,
130	              }}
131	              resizeMode="contain"
132	              controls
133	              paused
134	            />
135	          )}
136	        </Block>
137	      ) : (
138	        <Block
139	          width={ITEM_SIZE}
140	          height={ITEM_SIZE}
141	          background={Colors.white20}
142	          border={{ borderRadius: 4 }}
143	          overflow="hidden"
144	          align="center"
145	          justify="center"
146	        >
147	          {loading && <Loading isFullScreen={false} />}
148	        </Block>
149	      )}
150	    </Button.Wrapper>
151	  );
152	};
